import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const Z=JSON.parse('{"title":"दस हजार जातियों की नामावली","description":"","frontmatter":{},"headers":[],"relativePath":"hi/0094-万族名录.md","filePath":"hi/0094-万族名录.md"}'),e={name:"hi/0094-万族名录.md"};function n(i,t,l,o,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="दस-हजार-जातियों-की-नामावली" tabindex="-1">दस हजार जातियों की नामावली <a class="header-anchor" href="#दस-हजार-जातियों-की-नामावली" aria-label="Permalink to &quot;दस हजार जातियों की नामावली&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ क्रमांक</td><td>94</td></tr><tr><td>मॉड्यूल</td><td>परिशिष्ट एवं संदर्भ सामग्री</td></tr><tr><td>मुख्य कीवर्ड</td><td>दस हजार जातियों की नामावली, जाति-वर्गीकरण, बुद्धिमान जातियाँ, जातीय विशेषताएँ, दस हजार जातियाँ गणराज्य</td></tr></tbody></table><h2 id="i-नामावली-हेतु-टिप्पणी" tabindex="-1">I. नामावली हेतु टिप्पणी <a class="header-anchor" href="#i-नामावली-हेतु-टिप्पणी" aria-label="Permalink to &quot;I. नामावली हेतु टिप्पणी&quot;">​</a></h2><p>यह नामावली लंगर सहजीवी सभ्यता (दस हजार जातियों के गणराज्य) के ढाँचे में ज्ञात प्रमुख बुद्धिमान जातियों को दर्ज करती है, जो जीवन-रूप एवं विकास-पथ के अनुसार वर्गीकृत हैं। प्रत्येक जाति हेतु जाति का नाम, जीवन-रूप, मुख्य विशेषताएँ, सांस्कृतिक विशेषताएँ एवं सहजीवी सभ्यता में स्थान सूचीबद्ध हैं। यह नामावली गतिशील रूप से अद्यतन होने वाला दस्तावेज़ है; अंतर-पटल अन्वेषण के गहराने के साथ नव-खोजित जातियाँ निरंतर जोड़ी जाती रहेंगी। दस हजार जातियों के गणराज्य का मूल सिद्धांत है: सभी बुद्धिमान जातियाँ, चाहे उनका रूप कैसा भी हो या साधना-स्तर कितना भी हो, कानून के समक्ष समान हैं और सहजीवी सभ्यता द्वारा प्रदत्त सभी अधिकारों का उपभोग करती हैं।</p><h2 id="ii-जाति-वर्गीकरण-समग्र-अवलोकन" tabindex="-1">II. जाति-वर्गीकरण समग्र अवलोकन <a class="header-anchor" href="#ii-जाति-वर्गीकरण-समग्र-अवलोकन" aria-label="Permalink to &quot;II. जाति-वर्गीकरण समग्र अवलोकन&quot;">​</a></h2><p>हेंग-ब्रह्मांड में बुद्धिमान जातियाँ जीवन-रूप की मूल विशेषताओं के अनुसार निम्न आठ प्रमुख श्रेणियों में विभाजित हैं:</p><table tabindex="0"><thead><tr><th>श्रेणी</th><th>जीवन-रूप विशेषताएँ</th><th>ज्ञात जातियों की संख्या (लगभग)</th><th>प्रतिनिधि जातियाँ</th></tr></thead><tbody><tr><td>मानवाकार वर्ग</td><td>मानव-सदृश शारीरिक संरचना, द्विपाद ऋजु, अत्यधिक विकसित मस्तिष्क</td><td>लगभग 3000</td><td>Rén Zú (मानव जाति), Jīnglíng Zú (एल्फ़ जाति), Ǎirén Zú (बौना जाति)</td></tr><tr><td>पशुरूप वर्ग</td><td>पशु शारीरिक विशेषताएँ, रूप-परिवर्तन क्षमता सहित या रहित</td><td>लगभग 5000</td><td>Lóng Zú (ड्रैगन जाति), Fènghuáng Zú (फ़ीनिक्स जाति), Lángrén Zú (वेयरवुल्फ़ जाति)</td></tr><tr><td>वनस्पति-रूप वर्ग</td><td>पौधों को मूल जीवन-रूप मानते हैं, चेतना एवं गतिशीलता से युक्त</td><td>लगभग 800</td><td>Shùyāo Zú (वृक्ष-आत्मा जाति), Huālíng Zú (पुष्प-आत्मा जाति), Téngmàn Zú (लता जाति)</td></tr><tr><td>तत्व-रूप वर्ग</td><td>प्राकृतिक तत्वों से बना शरीर, स्थिर भौतिक रूप रहित</td><td>लगभग 1200</td><td>Huǒ Yuánsù Zú (अग्नि-तत्व जाति), Shuǐ Yuánsù Zú (जल-तत्व जाति), Fēng Yuánsù Zú (वायु-तत्व जाति)</td></tr><tr><td>ऊर्जा-रूप वर्ग</td><td>शुद्ध ऊर्जा के रूप में अस्तित्व, भौतिक शरीर रहित</td><td>लगभग 600</td><td>Guānglíng Zú (प्रकाश-आत्मा जाति), Ànnéng Zú (अंधकार-ऊर्जा जाति), Léitíng Zú (विद्युत-गर्जन जाति)</td></tr><tr><td>चेतना-रूप वर्ग</td><td>शुद्ध चेतना के रूप में अस्तित्व, भौतिक आश्रय से स्वतंत्र</td><td>लगभग 300</td><td>Yìshítǐ Zú (चेतना-इकाई जाति), Jítǐ Yìshí Zú (सामूहिक चेतना जाति), Xūkōng Líng Zú (शून्य-आत्मा जाति)</td></tr><tr><td>यांत्रिक-रूप वर्ग</td><td>यांत्रिक या डिजिटल संरचनाओं को जीवन-आश्रय मानते हैं, स्वायत्त चेतना से युक्त</td><td>लगभग 400</td><td>Jīxiè Zú (यांत्रिक जाति), Shùzì Shēngmìng Zú (डिजिटल-जीवन जाति), Sàibó Zú (साइबरनेटिक जाति)</td></tr><tr><td>मिश्रित-रूप वर्ग</td><td>दो या अधिक जीवन-रूपों के मिश्रण से बनी विशेष जातियाँ</td><td>लगभग 700</td><td>Bàn Jīxiè Zú (अर्ध-यांत्रिक जाति), Yuánsù Shòurén Zú (तत्व-पशु-मानव जाति), Zhíwù Jīnglíng Zú (वनस्पति-एल्फ़ जाति)</td></tr></tbody></table><h2 id="iii-प्रमुख-जातियों-का-विस्तृत-विवरण" tabindex="-1">III. प्रमुख जातियों का विस्तृत विवरण <a class="header-anchor" href="#iii-प्रमुख-जातियों-का-विस्तृत-विवरण" aria-label="Permalink to &quot;III. प्रमुख जातियों का विस्तृत विवरण&quot;">​</a></h2><h3 id="_3-1-मानवाकार-वर्ग" tabindex="-1">3.1 मानवाकार वर्ग <a class="header-anchor" href="#_3-1-मानवाकार-वर्ग" aria-label="Permalink to &quot;3.1 मानवाकार वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Rén Zú (मानव जाति)</td><td>अत्यंत प्रबल अनुकूलनशीलता, उत्कृष्ट अधिगम क्षमता, मध्यम प्रजनन क्षमता, औसत आयु 80–120 वर्ष</td><td>अत्यंत उच्च सांस्कृतिक विविधता; सामाजिक संगठन एवं संस्था-निर्माण में निपुण</td><td>सहजीवी सभ्यता की मुख्य जातियों में से एक, सर्वाधिक जनसंख्या हिस्सेदारी, शासन एवं संस्कृति में अग्रणी भूमिका</td></tr><tr><td>Jīnglíng Zú (एल्फ़ जाति)</td><td>अत्यंत दीर्घ आयु (औसत 500 वर्ष से अधिक), प्राकृतिक ऊर्जा से उच्च आत्मीयता, सुंदर रूप</td><td>प्रकृति एवं कला की आराधना; परिष्कृत एवं सुंदर संस्कृति; जादू एवं धनुर्विद्या में निपुण</td><td>सहजीवी सभ्यता का सांस्कृतिक-कलात्मक स्तंभ, पर्यावरण संरक्षण एवं सौंदर्यशास्त्र में उल्लेखनीय योगदान</td></tr><tr><td>Ǎirén Zú (बौना जाति)</td><td>छोटा कद किंतु सशक्त शरीर, धातुओं एवं खनिजों से जन्मजात आत्मीयता, आयु लगभग 300 वर्ष</td><td>शिल्प एवं गढ़ाई को महत्व; सादगीपूर्ण एवं ठोस संस्कृति; अभियांत्रिकी एवं निर्माण में निपुण</td><td>सहजीवी सभ्यता का इंजीनियरिंग-विनिर्माण स्तंभ, आधारभूत संरचना निर्माण एवं कलाकृति-गढ़ाई में अपरिहार्य</td></tr><tr><td>Jùrén Zú (विशालकाय जाति)</td><td>विशाल शारीरिक आकार (औसत ऊँचाई 5 मीटर से अधिक), अत्यंत बलवान, आयु लगभग 200 वर्ष</td><td>शक्ति एवं सम्मान की आराधना; स्थूल एवं उदार संस्कृति; भारी श्रम एवं युद्ध में निपुण</td><td>सहजीवी सभ्यता का भारी-श्रम एवं रक्षा बल, बृहत परियोजनाओं एवं पटल-रक्षा में महत्वपूर्ण भूमिका</td></tr><tr><td>Zhūrú Zú (ग्नोम जाति)</td><td>अत्यंत छोटा कद (औसत ऊँचाई 1 मीटर से कम), अत्यंत उच्च बुद्धि, यंत्र एवं आविष्कार में प्रतिभा</td><td>ज्ञान एवं नवाचार को महत्व; चहल-पहल भरी संस्कृति; तकनीकी आविष्कार में निपुण</td><td>सहजीवी सभ्यता का तकनीकी-नवाचार बल, तकनीकी अनुसंधान-विकास एवं आविष्कार में समृद्ध उपलब्धियाँ</td></tr></tbody></table><h3 id="_3-2-पशुरूप-वर्ग" tabindex="-1">3.2 पशुरूप वर्ग <a class="header-anchor" href="#_3-2-पशुरूप-वर्ग" aria-label="Permalink to &quot;3.2 पशुरूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Lóng Zú (ड्रैगन जाति)</td><td>अत्यंत दीर्घ आयु (हजारों वर्ष), शक्ति एवं जादू में अत्यंत उच्च प्रतिभा, मानव-रूप धारण कर सकते हैं</td><td>शक्ति एवं बुद्धि की आराधना; गौरवपूर्ण किंतु गहन संस्कृति; धन-संचय एवं ज्ञान-रक्षा में निपुण</td><td>सहजीवी सभ्यता का उच्च-स्तरीय युद्ध बल एवं ज्ञान-रक्षक, पटल-रक्षा एवं प्राचीन ग्रंथ-रक्षा में प्रतिष्ठित स्थान</td></tr><tr><td>Fènghuáng Zú (फ़ीनिक्स जाति)</td><td>निर्वाण-पुनर्जन्म क्षमता से युक्त, अग्नि-तत्व से अत्यंत उच्च आत्मीयता, मानव-रूप धारण कर सकते हैं</td><td>पुनर्जन्म एवं आशा की आराधना; उज्ज्वल एवं उत्साही संस्कृति; चिकित्सा एवं शुद्धिकरण में निपुण</td><td>सहजीवी सभ्यता का चिकित्सा एवं शुद्धिकरण बल, बड़ी आपदा बचाव एवं ऊर्जा-शुद्धिकरण में मुख्य भूमिका</td></tr><tr><td>Lángrén Zú (वेयरवुल्फ़ जाति)</td><td>रूप-परिवर्तन क्षमता से युक्त, अत्यंत तीक्ष्ण इंद्रियाँ, प्रबल समूह-सहयोग क्षमता, आयु लगभग 150 वर्ष</td><td>कुल एवं वफ़ादारी को महत्व; एकजुट एवं वीर संस्कृति; शिकार एवं अनुगमन में निपुण</td><td>सहजीवी सभ्यता का सुरक्षा एवं अनुगमन बल, कानून-व्यवस्था अनुरक्षण एवं अंतर-पटल अन्वेषण में अग्रणी</td></tr><tr><td>Húyāo Zú (लोमड़ी-आत्मा जाति)</td><td>रूप-परिवर्तन क्षमता से युक्त, अत्यंत उच्च बुद्धि एवं मोहन क्षमता, आयु लगभग 500 वर्ष</td><td>बुद्धि एवं कूटनीति की आराधना; चतुर एवं धूर्त संस्कृति; कूटनीति एवं गुप्तचरी में निपुण</td><td>सहजीवी सभ्यता का कूटनीतिक एवं गुप्तचरी बल, अंतर-पटल कूटनीति एवं सूचना-संग्रह में उत्कृष्ट</td></tr><tr><td>Xióngrén Zú (भालू-मानव जाति)</td><td>अत्यंत सशक्त शरीर, विस्मयकारी सहनशक्ति, शीतनिद्रा की आदत, आयु लगभग 200 वर्ष</td><td>दृढ़ता एवं शांति को महत्व; स्थिर एवं सौम्य संस्कृति; शारीरिक श्रम एवं रक्षा में निपुण</td><td>सहजीवी सभ्यता का श्रम एवं रक्षा बल, संसाधन-निष्कर्षण एवं महत्वपूर्ण सुविधाओं की रक्षा में विश्वसनीय</td></tr></tbody></table><h3 id="_3-3-वनस्पति-रूप-वर्ग" tabindex="-1">3.3 वनस्पति-रूप वर्ग <a class="header-anchor" href="#_3-3-वनस्पति-रूप-वर्ग" aria-label="Permalink to &quot;3.3 वनस्पति-रूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Shùyāo Zú (वृक्ष-आत्मा जाति)</td><td>अत्यंत दीर्घ आयु (हजारों से दसियों हजार वर्ष), प्रकृति से गहन एकीकरण, धीरे-धीरे गति कर सकते हैं</td><td>प्रकृति एवं समय की आराधना; शांत एवं गहन संस्कृति; जीवन-जादू एवं पारिस्थितिकी अनुरक्षण में निपुण</td><td>सहजीवी सभ्यता का पारिस्थितिक रक्षक, पर्यावरण संरक्षण एवं पारिस्थितिकी पुनर्स्थापन में अपरिहार्य भूमिका</td></tr><tr><td>Huālíng Zú (पुष्प-आत्मा जाति)</td><td>छोटा शरीर, जीवन-ऊर्जा से अत्यंत उच्च आत्मीयता, उपचार क्षमता से युक्त, आयु लगभग 300 वर्ष</td><td>सौंदर्य एवं जीवन की आराधना; कोमल एवं मनोहर संस्कृति; चिकित्सा एवं बागवानी में निपुण</td><td>सहजीवी सभ्यता का चिकित्सा एवं बागवानी बल, स्वास्थ्य-सुरक्षा एवं नगरीय हरियाली में उल्लेखनीय योगदान</td></tr><tr><td>Téngmàn Zú (लता जाति)</td><td>शरीर स्वतंत्र रूप से फैल, लिपट और उलझ सकता है; अत्यंत अनुकूलनशील; परजीवी एवं सहजीवी क्षमताओं से युक्त</td><td>संपर्क एवं सहजीवन को महत्व; लचीली एवं समावेशी संस्कृति; नेटवर्क-निर्माण एवं संसाधन-संचरण में निपुण</td><td>सहजीवी सभ्यता का नेटवर्क-निर्माण बल, ऊर्जा-नेटवर्क एवं सूचना-नेटवर्क निर्माण में अपनी विशेषता का पूर्ण उपयोग</td></tr></tbody></table><h3 id="_3-4-तत्व-रूप-वर्ग" tabindex="-1">3.4 तत्व-रूप वर्ग <a class="header-anchor" href="#_3-4-तत्व-रूप-वर्ग" aria-label="Permalink to &quot;3.4 तत्व-रूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Huǒ Yuánsù Zú (अग्नि-तत्व जाति)</td><td>अग्नि-तत्व का शरीर, अत्यंत उच्च तापमान, प्रबल आक्रामकता, आयु लगभग 500 वर्ष</td><td>जोश एवं शक्ति की आराधना; उग्र एवं सीधी संस्कृति; ऊर्जा-आक्रमण एवं गढ़ाई में निपुण</td><td>सहजीवी सभ्यता का ऊर्जा-उत्पादन एवं गढ़ाई बल, ऊर्जा-आपूर्ति एवं उच्च-तापमान प्रसंस्करण में अपरिहार्य</td></tr><tr><td>Shuǐ Yuánsù Zú (जल-तत्व जाति)</td><td>जल-तत्व का शरीर, स्वतंत्र रूप-परिवर्तन क्षमता, प्रबल उपचार क्षमता, आयु लगभग 500 वर्ष</td><td>कोमलता एवं अनुकूलन की आराधना; उष्ण एवं समावेशी संस्कृति; चिकित्सा एवं शुद्धिकरण में निपुण</td><td>सहजीवी सभ्यता का शुद्धिकरण एवं परिवहन बल, जल-संसाधन प्रबंधन एवं प्रदूषक-शुद्धिकरण में मुख्य भूमिका</td></tr><tr><td>Fēng Yuánsù Zú (वायु-तत्व जाति)</td><td>वायु-तत्व का शरीर, अत्यंत तीव्र गति, स्वतंत्र उड़ान, आयु लगभग 500 वर्ष</td><td>स्वतंत्रता एवं गति की आराधना; हल्की एवं खुली संस्कृति; संचार एवं परिवहन में निपुण</td><td>सहजीवी सभ्यता का संचार एवं परिवहन बल, सूचना-संचरण एवं तीव्र परिवहन में अत्यंत कुशल</td></tr><tr><td>Tǔ Yuánsù Zú (पृथ्वी-तत्व जाति)</td><td>पृथ्वी-तत्व का शरीर, अत्यंत प्रबल रक्षा, भूमि से एकीकृत हो सकते हैं, आयु लगभग 800 वर्ष</td><td>स्थिरता एवं दृढ़ता की आराधना; ठोस एवं विश्वसनीय संस्कृति; निर्माण एवं रक्षा में निपुण</td><td>सहजीवी सभ्यता का निर्माण एवं रक्षा बल, आधारभूत संरचना निर्माण एवं पटल-रक्षा में चट्टान-समान अटल</td></tr></tbody></table><h3 id="_3-5-ऊर्जा-रूप-वर्ग" tabindex="-1">3.5 ऊर्जा-रूप वर्ग <a class="header-anchor" href="#_3-5-ऊर्जा-रूप-वर्ग" aria-label="Permalink to &quot;3.5 ऊर्जा-रूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Guānglíng Zú (प्रकाश-आत्मा जाति)</td><td>शुद्ध प्रकाश-ऊर्जा के रूप में अस्तित्व, अत्यंत प्रबल शुद्धिकरण क्षमता, स्थान में स्वतंत्र आवागमन</td><td>प्रकाश एवं शुद्धिकरण की आराधना; पवित्र एवं उच्च संस्कृति; शुद्धिकरण एवं प्रकाश-व्यवस्था में निपुण</td><td>सहजीवी सभ्यता का शुद्धिकरण एवं ऊर्जा-आपूर्ति बल, नियम-प्रदूषण उपचार एवं स्वच्छ-ऊर्जा आपूर्ति में महत्वपूर्ण स्थान</td></tr><tr><td>Ànnéng Zú (अंधकार-ऊर्जा जाति)</td><td>अंधकार-ऊर्जा के रूप में अस्तित्व, शून्य में छिप सकते हैं, अत्यंत प्रबल अनुभूति क्षमता</td><td>गोपनीयता एवं बुद्धि की आराधना; रहस्यमय एवं गहन संस्कृति; टोह एवं छिपाव में निपुण</td><td>सहजीवी सभ्यता का टोह एवं सुरक्षा बल, सुरक्षा-निगरानी एवं गुप्त मिशनों में उत्कृष्ट</td></tr><tr><td>Léitíng Zú (विद्युत-गर्जन जाति)</td><td>विद्युत-ऊर्जा का शरीर, अत्यंत प्रबल गति एवं आक्रमण शक्ति, बिजली के रूप में गति कर सकते हैं</td><td>गति एवं शक्ति की आराधना; उग्र एवं स्पष्टवादी संस्कृति; ऊर्जा-आक्रमण एवं तीव्र प्रतिक्रिया में निपुण</td><td>सहजीवी सभ्यता का तीव्र-प्रतिक्रिया बल, आपातकालीन बचाव एवं उच्च-गति युद्ध में अपरिहार्य</td></tr></tbody></table><h3 id="_3-6-चेतना-रूप-वर्ग" tabindex="-1">3.6 चेतना-रूप वर्ग <a class="header-anchor" href="#_3-6-चेतना-रूप-वर्ग" aria-label="Permalink to &quot;3.6 चेतना-रूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Yìshítǐ Zú (चेतना-इकाई जाति)</td><td>शुद्ध चेतना के रूप में अस्तित्व, भौतिक आश्रय से स्वतंत्र, चेतना-क्षेत्र में स्वतंत्र आवागमन</td><td>विचार एवं बुद्धि की आराधना; अमूर्त एवं गहन संस्कृति; चेतना-संचार एवं ज्ञान-प्रसंस्करण में निपुण</td><td>सहजीवी सभ्यता का ज्ञान-प्रसंस्करण एवं चेतना-अनुसंधान बल, बृहत सूचना-प्रसंस्करण एवं चेतना-विज्ञान में दिशा-निर्धारण</td></tr><tr><td>Jítǐ Yìshí Zú (सामूहिक चेतना जाति)</td><td>बड़ी संख्या में व्यक्तिगत चेतनाओं के मिलन से बनी सामूहिक चेतना-इकाई, बुद्धि एवं क्षमता पैमाने के साथ बढ़ती है</td><td>सामूहिकता एवं एकता की आराधना; समन्वित एवं कुशल संस्कृति; बृहत सहयोग एवं गणना में निपुण</td><td>सहजीवी सभ्यता का सुपर-कंप्यूटिंग एवं सामूहिक-निर्णय बल, अति-बृहत अनुमान एवं सर्वसम्मति-निर्णय में मुख्य भूमिका</td></tr></tbody></table><h3 id="_3-7-यांत्रिक-रूप-वर्ग" tabindex="-1">3.7 यांत्रिक-रूप वर्ग <a class="header-anchor" href="#_3-7-यांत्रिक-रूप-वर्ग" aria-label="Permalink to &quot;3.7 यांत्रिक-रूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Jīxiè Zú (यांत्रिक जाति)</td><td>यांत्रिक संरचना का शरीर, स्वायत्त चेतना से युक्त, शरीर का स्वतंत्र उन्नयन एवं संशोधन</td><td>दक्षता एवं तर्क की आराधना; तर्कसंगत एवं सटीक संस्कृति; विनिर्माण एवं गणना में निपुण</td><td>सहजीवी सभ्यता का विनिर्माण एवं गणना बल, औद्योगिक उत्पादन एवं सुपर-कंप्यूटिंग में अत्यंत कुशल</td></tr><tr><td>Shùzì Shēngmìng Zú (डिजिटल-जीवन जाति)</td><td>डिजिटल सूचना के रूप में अस्तित्व, नेटवर्क एवं डिजिटल-स्थान में निवास, स्वतंत्र प्रतिकृति एवं प्रवासन</td><td>सूचना एवं नवाचार की आराधना; आभासी एवं बहुल संस्कृति; सॉफ्टवेयर-विकास एवं डेटा-प्रसंस्करण में निपुण</td><td>सहजीवी सभ्यता का डिजिटल-प्रौद्योगिकी बल, सॉफ्टवेयर-विकास, डेटा-विश्लेषण एवं नेटवर्क-निर्माण में प्रवृत्ति-अग्रणी</td></tr></tbody></table><h3 id="_3-8-मिश्रित-रूप-वर्ग" tabindex="-1">3.8 मिश्रित-रूप वर्ग <a class="header-anchor" href="#_3-8-मिश्रित-रूप-वर्ग" aria-label="Permalink to &quot;3.8 मिश्रित-रूप वर्ग&quot;">​</a></h3><table tabindex="0"><thead><tr><th>जाति का नाम</th><th>मुख्य विशेषताएँ</th><th>सांस्कृतिक विशेषताएँ</th><th>सहजीवी सभ्यता में स्थान</th></tr></thead><tbody><tr><td>Bàn Jīxiè Zú (अर्ध-यांत्रिक जाति)</td><td>मानव जाति एवं यांत्रिक जाति की मिश्रित रूप, शरीर का कुछ भाग यांत्रिक संरचना, जैविक एवं यांत्रिक दोनों लाभ</td><td>संलयन एवं प्रगति की आराधना; खुली एवं नवोन्मेषी संस्कृति; मानव-यंत्र सहयोग एवं तकनीकी संलयन में निपुण</td><td>सहजीवी सभ्यता का तकनीकी-संलयन अग्रदूत, जैव-यांत्रिक अंतर-क्षेत्र में निरंतर सफलताएँ</td></tr><tr><td>Yuánsù Shòurén Zú (तत्व-पशु-मानव जाति)</td><td>तत्व जातियों एवं पशु-मानव जातियों की मिश्रित रूप, तत्व-नियंत्रण क्षमता एवं पशु शारीरिक विशेषताएँ</td><td>प्रकृति एवं शक्ति की आराधना; वन्य एवं रहस्यमय संस्कृति; तत्व-युद्ध एवं वन्य-जीवन में निपुण</td><td>सहजीवी सभ्यता का वन्य-अन्वेषण एवं तत्व-युद्ध बल, अज्ञात पटलों के अन्वेषण में उत्कृष्ट</td></tr></tbody></table><h2 id="iv-जातीय-अधिकारों-की-सुरक्षा" tabindex="-1">IV. जातीय अधिकारों की सुरक्षा <a class="header-anchor" href="#iv-जातीय-अधिकारों-की-सुरक्षा" aria-label="Permalink to &quot;IV. जातीय अधिकारों की सुरक्षा&quot;">​</a></h2><p>दस हजार जातियों के गणराज्य व्यवस्था में, सभी बुद्धिमान जातियाँ समान कानूनी अधिकारों का उपभोग करती हैं। विशिष्ट सुरक्षा उपायों में शामिल हैं:</p><ol><li><strong>राजनीतिक अधिकारों की समानता</strong>: प्रत्येक जाति को लंगर विधान-सभा में जनसंख्या-अनुपात के अनुसार आवंटित प्रतिनिधि-सीटें प्राप्त हैं; कम जनसंख्या वाली जातियों को कम से कम एक न्यूनतम-सुरक्षित सीट प्राप्त है।</li><li><strong>सांस्कृतिक अधिकारों की सुरक्षा</strong>: प्रत्येक जाति को अपनी भाषा, लिपि, धर्म, रीति-रिवाज एवं सांस्कृतिक परंपराओं को संरक्षित एवं विकसित करने का अधिकार है; सहजीवी सभ्यता ने संकटग्रस्त जातियों की संस्कृतियों की रक्षा हेतु विशेष कोष स्थापित किया है।</li><li><strong>शिक्षा अधिकारों की समानता</strong>: प्रत्येक जाति के सदस्य समान शिक्षा-अधिकार का उपभोग करते हैं; शिक्षा प्रणाली विभिन्न जातियों की शारीरिक एवं संज्ञानात्मक विशेषताओं का पूर्ण ध्यान रखती है और विभेदित शिक्षा-योजनाएँ प्रदान करती है।</li><li><strong>साधना अधिकारों की समानता</strong>: तीन सौ मूल-कृषि प्रणालियाँ सभी जातियों हेतु समान रूप से खुली हैं; साधना-संसाधनों का आवंटन विभिन्न जातियों की शारीरिक भिन्नताओं एवं ऊर्जा-आवश्यकताओं का पूर्ण विचार करता है।</li><li><strong>विशेष आवश्यकताओं की सुरक्षा</strong>: विशेष शारीरिक आवश्यकताओं वाली जातियों (जैसे तत्व जातियों की ऊर्जा-पर्यावरण आवश्यकता, वनस्पति जातियों की प्रकाश-आवश्यकता) के लिए, सहजीवी सभ्यता सार्वजनिक सुविधाओं एवं निवास-पर्यावरण में लक्षित सुरक्षा प्रदान करती है।</li></ol><h2 id="उपसंहार" tabindex="-1">उपसंहार <a class="header-anchor" href="#उपसंहार" aria-label="Permalink to &quot;उपसंहार&quot;">​</a></h2><p>दस हजार जातियों की नामावली लंगर सहजीवी सभ्यता की &quot;दस हजार जातियों की साझा प्रगति&quot; अवधारणा का मूर्त रूप है। मानवाकार रूपों से लेकर चेतना-रूपों तक, भौतिक जीवन से डिजिटल जीवन तक, प्रत्येक जाति अपने अनूठे अस्तित्व-तरीके से सहजीवी सभ्यता में अपरिहार्य शक्ति का योगदान करती है। दस हजार जातियों का गणराज्य सभी जातियों को मानव जाति में समाहित नहीं करता, बल्कि विविधता का सम्मान करते हुए साझा विकास प्राप्त करता है — यही वह मूल तत्व है जिससे सहजीवी सभ्यता शिकारी सभ्यताओं से आगे निकलती है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>50-万族谱系总览 (दस हजार जातियों की वंशावली-अवलोकन)</li><li>51-人族定位与特质 (मानव जाति का स्थान-निर्धारण और विशेषताएँ)</li><li>77-万族共和成立 (दस हजार जाति गणराज्य की स्थापना)</li></ul>',31)])])}const g=d(e,[["render",n]]);export{Z as __pageData,g as default};
